 for n,q in [('left_hip_pitch',q0['left_hip_pitch']+pitch),('right_hip_pitch',q0['right_hip_pitch']+pitch),('left_hip_roll',q0['left_hip_roll']+roll),('right_hip_roll',q0['right_hip_roll']-roll)]:setq(a,n,q)
 last=r.submit('joint_position',a[None,:],dt=.02,interpolate='hold',cameras=['room_camera'],video='none',note='positive hip arrest after forward pitch')
 cur=np.asarray(last.proprio)[-1]
 if k%10==9 or last.done:log.append({'step':k+1,'g':cur[-3:].tolist(),'w':cur[-6:-3].tolist(),'done':last.done,'reason':last.meta.get('reason')})
 if last.done:break
last.save('/app/output/arrest_balance_positive');open('/app/output/arrest_balance_positive.json','w').write(json.dumps(log,indent=2))
print('status',json.dumps(r.status()))
print('log',[(x['step'],np.round(x['g'],2).tolist(),np.round(x['w'],2).tolist(),x['reason']) for x in log])
